// ── tracing.ts ─────────────────────────────────────────────
import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';

const sdk = new NodeSDK({
  traceExporter: new OTLPTraceExporter({
    url: 'http://localhost:4318/v1/traces',
  }),
  instrumentations: [getNodeAutoInstrumentations()],
});

// sdk.start() is where auto-instrumentation monkey-patches the
// http/framework modules — but it can only patch modules that
// have not been required/loaded yet.
sdk.start();

export { sdk };


// ── main.ts ────────────────────────────────────────────────
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
// AppModule transitively requires express/http right here, at
// the top of the file — before tracing has a chance to start.

import './tracing';
// The SDK boots only after the framework module object is
// already resolved and cached by Node's module loader.

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000);
}

bootstrap();


// ── orders.controller.ts ──────────────────────────────────
import { Controller, Get } from '@nestjs/common';
import { trace } from '@opentelemetry/api';

@Controller('orders')
export class OrdersController {
  @Get()
  async getOrders() {
    const tracer = trace.getTracer('app');
    const span = tracer.startSpan('business-work');
    try {
      const orders = await this.loadOrders();
      return orders;
    } finally {
      // Correctly ended — but with no auto-instrumented server
      // span ever created, this manual span has no parent to
      // attach to, so it may not surface as expected either.
      span.end();
    }
  }

  private async loadOrders() {
    return [{ id: 1, name: 'Order #1' }];
  }
}
